const body = $input.first().json.body;
const canal = body.canal || 'instagram_dm';
let leadIdentifier = '', mensajeActual = '', subscriberId = '';
const fuente = body.fuente || 'desconocido';

if (canal === 'instagram_dm') {
  leadIdentifier = 'ig_' + (body.ig_username || body.subscriber_id || 'unknown');
  mensajeActual = body.last_message || '';
  subscriberId = body.subscriber_id || '';
} else if (canal === 'facebook') {
  leadIdentifier = 'fb_' + (body.fb_psid || body.subscriber_id || 'unknown');
  mensajeActual = body.last_message || '';
  subscriberId = body.subscriber_id || '';
} else if (canal === 'whatsapp') {
  const waMsg = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  const numero = waMsg?.from || body.from || 'unknown';
  leadIdentifier = 'wa_' + numero;
  mensajeActual = waMsg?.text?.body || body.last_message || '';
  subscriberId = numero;
}

if (!mensajeActual.trim()) {
  return [{ json: { skip: true } }];
}

return [{ json: { skip: false, canal, fuente, leadIdentifier, mensajeActual: mensajeActual.trim(), subscriberId } }];

const normalizado = $('Normalizar Payload').first().json;
const airtableRecord = $input.first().json;

const historialExistente = airtableRecord?.fields?.historial || airtableRecord?.historial || '';
const perfilLead = airtableRecord?.fields?.perfil_lead || airtableRecord?.perfil_lead || 'sin_clasificar';
const etapaConversion = airtableRecord?.fields?.etapa_conversion || airtableRecord?.etapa_conversion || 'apertura';
const recordId = airtableRecord?.id || '';

const historialConMensaje = historialExistente
  ? historialExistente + '\n[LEAD]: ' + normalizado.mensajeActual
  : '[LEAD]: ' + normalizado.mensajeActual;

const historialTruncado = historialConMensaje.length > 3000
  ? '...(historial truncado)\n' + historialConMensaje.slice(-3000)
  : historialConMensaje;

return [{
  json: { ...normalizado, historial: historialTruncado, historialExistente, perfilLead, etapaConversion, recordId }
}];

const agentOutput = $input.first().json.output || '';

const partes = agentOutput
  .split(/\n---\n|^---$/m)
  .map(p => p.trim())
  .filter(p => p.length > 0 && p !== '---');

const notificarCierre = agentOutput.includes('[NOTIFICAR_CIERRE]');
const notificarAgenda = agentOutput.includes('[NOTIFICAR_AGENDA]');
const notificarDescalificado = agentOutput.includes('[NOTIFICAR_DESCALIFICADO]');
const notificarFollowup = agentOutput.includes('[NOTIFICAR_FOLLOWUP]');

const mensajesConDelay = partes.map((texto, idx) => {
  const textoLimpio = texto.replace(/\[NOTIFICAR_[A-Z_]+\]/g, '').trim();
  const delay = idx === 0
    ? Math.min(Math.max(textoLimpio.length * 50, 1500), 4000)
    : Math.min(Math.max(textoLimpio.length * 50, 1000), 6000);
  return { texto: textoLimpio, delay };
});

const respuestaAgente = mensajesConDelay.map(m => m.texto).join(' ');
const lead = $('Preparar Datos del Lead').first().json;
const historialNuevo = lead.historial + '\n[ASESOR]: ' + respuestaAgente;
const historialTruncado = historialNuevo.length > 3000
  ? '...(truncado)\n' + historialNuevo.slice(-3000)
  : historialNuevo;

let nuevaEtapa = lead.etapaConversion;
if (notificarCierre) nuevaEtapa = 'ganado';
else if (notificarDescalificado) nuevaEtapa = 'descalificado';
else if (notificarAgenda) nuevaEtapa = 'agenda_solicitada';
else if (notificarFollowup) nuevaEtapa = 'pendiente_followup';
else if (nuevaEtapa === 'apertura') nuevaEtapa = 'diagnostico';
else if (nuevaEtapa === 'diagnostico' && agentOutput.includes('$')) nuevaEtapa = 'propuesta';

return [{
  json: {
    ...lead,
    mensajesConDelay,
    historialNuevo: historialTruncado,
    nuevaEtapa,
    notificarCierre, notificarAgenda, notificarDescalificado, notificarFollowup,
    totalMensajes: mensajesConDelay.length
  }
}];

const parsed = $('Parsear Respuesta').first().json;
const lead = $('Preparar Datos del Lead').first().json;
let emoji = '🔔', tipo = 'Seguimiento';
if (parsed.notificarCierre) { emoji = '🎉'; tipo = 'VENTA CERRADA'; }
else if (parsed.notificarAgenda) { emoji = '📅'; tipo = 'AGENDA SOLICITADA'; }
else if (parsed.notificarDescalificado) { emoji = '❌'; tipo = 'Lead descalificado'; }
else if (parsed.notificarFollowup) { emoji = '🔄'; tipo = 'Follow-up pendiente'; }
const canalEmoji = { instagram_dm: '📸', whatsapp: '💬', facebook: '👍' };
const msg = `${emoji} *${tipo}*\n\nLead: \`${lead.leadIdentifier}\`\nCanal: ${canalEmoji[lead.canal] || ''} ${lead.canal}\nFuente: ${lead.fuente}\nPerfil: ${lead.perfilLead}\nEtapa: ${parsed.nuevaEtapa}\n\n_Ver historial en Airtable._`;
return [{ json: { mensaje: msg } }];
